    if (h > 0) return h + '小时' + m + '分';
    return m + '分';
  };

  /** 模糊化的等待描述：复刻原版神秘感，不给准确倒计时 */
  util.vagueWait = function (remainMs, totalMs) {
    var p = totalMs > 0 ? 1 - remainMs / totalMs : 1;
