             { f: 1318, d: 0.10, t: 'square', g: 0.05, delay: 0.18 },
             { f: 1568, d: 0.38, t: 'square', g: 0.06, delay: 0.27 }],
    blip:   [{ f: 880, d: 0.05, t: 'sine', g: 0.05 }],
