    } else if (!res.reached) {
      parts.push(fill(U.pick(rand, T.turnedBackOpen), vars));
    } else if (res.redirected) {
      parts.push(fill(U.pick(rand, T.redirectedOpen), vars));
    } else if (res.destination && res.destination.arriveLines && rand() < 0.55) {
